// MarshalJSONTo writes the container as a JSON array.
//
// One pass over the elements and straight into the encoder. No part of the
// document is assembled anywhere else first, so what it costs to write a
// container is what it costs to write its elements and nothing besides.
func (c Credentials) MarshalJSONTo(enc *jsontext.Encoder) error {
	if err := enc.WriteToken(jsontext.BeginArray); err != nil {
		return err
	}
	for v := range c.All() {
		if err := encodePeopleCredentialJSONTo(enc, v); err != nil {
			return err
		}
	}
	return enc.WriteToken(jsontext.EndArray)
}

// credentialsCounting counts the bytes a writer accepted.
//
// The encoder buffers, so what it has written and what the writer beneath it
// has taken are two numbers. This is the second, which is the one a caller
// copying from the container is entitled to.
type credentialsCounting struct {
	to io.Writer
	n  int64
}

// Write passes the bytes on and counts the ones that were taken.
func (w *credentialsCounting) Write(p []byte) (int, error) {
	n, err := w.to.Write(p)
	w.n += int64(n)
	return n, err
}

// WriteTo writes the container to w as a JSON array, and reports how many bytes
// reached w.
//
// Straight to w rather than into a buffer this then copies, so a container of
// any size costs the encoder's own buffer and no more. The document ends with
// a newline, which is what an encoder leaves between the values of a stream.
func (c Credentials) WriteTo(w io.Writer) (int64, error) {
	counted := credentialsCounting{to: w}
	enc := jsontext.NewEncoder(&counted, jsontext.AllowDuplicateNames(true))
	if err := c.MarshalJSONTo(enc); err != nil {
		return counted.n, err
	}
	return counted.n, nil
}

// UnmarshalJSONFrom reads a JSON array into the container.
//
// What the container held is dropped first, so reading into one twice leaves
// the second document rather than both — which is what reading a document
// into a value means everywhere else. A JSON null empties it and reads
// nothing else: a container is empty or holds elements, so null and an empty
// array are read alike and both are written back as an empty array.
//
// The elements are handed over one at a time as they are read, so the
// document is never held in memory beside the container being filled from
// it.
func (c *Credentials) UnmarshalJSONFrom(dec *jsontext.Decoder) error {
	if dec.PeekKind() == 'n' {
		if _, err := dec.ReadToken(); err != nil {
			return err
		}
		c.Reset()
		return nil
	}
	if kind := dec.PeekKind(); kind != '[' {
		// A decoder that failed reports no kind at all, and reading is what
		// says why; a document of the wrong shape reads fine and is wrong.
		if _, err := dec.ReadToken(); err != nil {
			return err
		}
		return fmt.Errorf("cannot read Credentials from a JSON %s", kind)
	}
	if _, err := dec.ReadToken(); err != nil {
		return err
	}
	c.Reset()

	var failed error
	c.AppendSeq(func(yield func(Credential) bool) {
		for dec.PeekKind() != ']' {
			var v Credential
			if err := decodePeopleCredentialJSONFrom(dec, &v); err != nil {
				failed = err
				return
			}
			if !yield(v) {
				return
			}
		}
	})

	if failed != nil {
		return failed
	}
	if kind := dec.PeekKind(); kind != ']' && kind != 0 {
		return errors.New("Credentials stopped taking elements before the JSON array ended")
	}
	_, err := dec.ReadToken()
	return err
}

// ReadFrom reads one JSON array from r into the container, and reports how many
// bytes that array took.
//
// One array rather than everything r holds, because a JSON document ends
// where it ends. The decoder reads r in blocks, so bytes following the array
// may already have been taken out of r and are dropped with it: this reads a
// reader holding one document, and a stream of them is read through a decoder
// that outlives each. A reader holding nothing reports io.EOF.
func (c *Credentials) ReadFrom(r io.Reader) (int64, error) {
	dec := jsontext.NewDecoder(r)
	if err := c.UnmarshalJSONFrom(dec); err != nil {
		return dec.InputOffset(), err
	}
	return dec.InputOffset(), nil
}

