// PersonBuilder builds one Person, a field at a time.
//
// Each setter answers with the builder, so the fields may be written in
// whatever order suits the caller and the compiler still checks every one. The
// zero value is a builder holding nothing, so a variable of this type is ready
// without being made.
//
// Build refuses a value whose required fields were never given, and reports
// every one of them rather than the first.
type PersonBuilder struct {
	// held is the value being built, which every setter writes one field of.
	held Person

	// given records which of the required fields have been given, in the order
	// Build reports them: Name, Email.
	//
	// Recorded rather than read off the value, because a field given the zero
	// value was still given: a caller who set it meant to, and whether the zero
	// value will do is a rule rather than an omission.
	given [2]bool
}

// NewPersonBuilder returns a builder for one Person.
func NewPersonBuilder() *PersonBuilder { return &PersonBuilder{} }

// ID sets the ID of the Person being built.
func (b *PersonBuilder) ID(v int) *PersonBuilder {
	b.held.ID = v
	return b
}

// Name sets the Name of the Person being built.
func (b *PersonBuilder) Name(v string) *PersonBuilder {
	b.held.Name = v
	b.given[0] = true
	return b
}

// Email sets the Email of the Person being built.
func (b *PersonBuilder) Email(v string) *PersonBuilder {
	b.held.Email = v
	b.given[1] = true
	return b
}

// Age sets the Age of the Person being built.
func (b *PersonBuilder) Age(v int) *PersonBuilder {
	b.held.Age = v
	return b
}

// Aliases sets the Aliases of the Person being built.
func (b *PersonBuilder) Aliases(v []string) *PersonBuilder {
	b.held.Aliases = v
	return b
}

// Build returns the Person that was built.
//
// A field the author tagged as one a value has to carry, and whose setter was
// never called, is reported rather than left at its zero. Every one of them
// rather than the first, because a caller filling in a form wants the whole
// list.
//
// What was given is not checked here. A caller who set a field has set it, and
// whether what they set is any good is what the rules on the field say — which
// is a different question, asked somewhere a rule added to the tag reaches.
func (b *PersonBuilder) Build() (Person, error) {
	var failed ValidationErrors

	if !b.given[0] {
		failed = append(failed, ValidationError{Path: "Name", Rule: "required", Want: "a value"})
	}
	if !b.given[1] {
		failed = append(failed, ValidationError{Path: "Email", Rule: "required", Want: "a value"})
	}

	if len(failed) > 0 {
		var zero Person
		return zero, failed
	}
	return b.held, nil
}

// clonePerson returns a copy of v that shares nothing with it.
//
// The value's own method holds the body; this is what generated code
// calls, so that a caller names one function whether or not the type
// is one a method could be declared on.
func clonePerson(v Person) Person {
	return v.Clone()
}

// Clone returns a copy of the Person that shares nothing with it.
//
// Everything reachable is copied, so what is done to the copy is invisible in
// the original and the other way round. The copy starts as an assignment, which
// is already the whole of it for a field holding a number, a string or anything
// else made only of those; what follows is the fields for which an assignment
// would have copied a reference rather than what it refers to.
func (v Person) Clone() Person {
	out := v

	out.Aliases = slices.Clone(v.Aliases)
	return out
}

// String returns the subject as the display tags on its fields ask for it.
//
// The fields in the order they were written, separated by a space, each
// labelled where its tag gave it a name. It is a rendering for a person to
// read rather than a format anything should parse: nothing here escapes a
// separator that turns up inside a value, because a reader can see what
// happened and a parser was never the point.
func (v Person) String() string {
	var b strings.Builder

	b.WriteString(v.Name)

	b.WriteString(" ")
	b.WriteString("age=")
	b.WriteString(strconv.FormatInt(int64(v.Age), 10))

	return b.String()
}

// String returns what this member is called.
//
// A value nobody declared renders as the type and the value it holds, rather
// than as one of the members. It is not one, and a rendering that said
// otherwise would let an undeclared value travel through a log and a document
// with nothing saying where it came from.
func (v Status) String() string {
	switch v {
	case StatusPending:
		return "pending"
	case StatusActive:
		return "active"
	case StatusRevoked:
		return "revoked"
	}
	return "Status(" + strconv.FormatInt(int64(v), 10) + ")"
}

// Valid reports whether this is a member of the set.
//
// Worth asking, because a value of the type is not necessarily one of them: the
// type is the whole range of whatever it is a name for, and the set is the
// constants declared of it. A number off a wire, out of a database, or cast
// from an integer is a value nobody declared, and there is no zero to compare
// against — for a set counted from iota the zero is an ordinary member.
func (v Status) Valid() bool {
	switch v {
	case StatusPending,
		StatusActive,
		StatusRevoked:
		return true
	}
	return false
}

// ValuesStatus returns every member, in the order they were declared.
//
// Declaration order rather than sorted, because that is the order the constant
// block reads in and the order a run counted by iota means. A fresh slice each
// call, so that a caller sorting or appending to what they were given does not
// change what the next one is given.
func ValuesStatus() []Status {
	return []Status{
		StatusPending,
		StatusActive,
		StatusRevoked,
	}
}

// ParseStatus returns the member with this name.
//
// Every name a member has, which for a set with two names for one value is both
// of them: aliasing is what a package does while a name is being changed, and a
// reader that took only the new one would break every caller the moment the old
// one was added.
func ParseStatus(s string) (Status, error) {
	switch s {
	case "pending":
		return StatusPending, nil
	case "active":
		return StatusActive, nil
	case "revoked":
		return StatusRevoked, nil
	}

	var zero Status
	return zero, errors.New(strconv.Quote(s) + " is not a member of Status")
}

// MarshalText returns the member's name as text.
//
// The same text String renders, because a closed set has one spelling and two
// would be a value that read one way and travelled another. It is also what a
// JSON codec reaches for when the type has none of its own, so the member goes
// over the wire under the name it is known by rather than as the number behind
